const AWS = require('aws-sdk');
const dynamodb = new AWS.DynamoDB.DocumentClient();
const crypto = require('crypto');

// Lambda handler for user profile management API
exports.handler = async (event) => {
  const headers = event.headers || {};
  const httpMethod = event.httpMethod;
  const body = event.body ? JSON.parse(event.body) : {};

  // Extract session from cookie
  const cookies = parseCookies(headers.Cookie || headers.cookie || '');
  const sessionToken = cookies['session_id'];

  if (!sessionToken) {
    return { statusCode: 401, body: JSON.stringify({ error: 'Unauthorized' }) };
  }

  // Validate session - get user from sessions table
  const sessionResult = await dynamodb.get({
    TableName: 'UserSessions',
    Key: { sessionId: sessionToken }
  }).promise();

  if (!sessionResult.Item || sessionResult.Item.expiresAt < Date.now()) {
    return { statusCode: 401, body: JSON.stringify({ error: 'Session expired' }) };
  }

  const authenticatedUserId = sessionResult.Item.userId;

  // NOTE: No CSRF token validation - relies on cookie-based auth only
  // The Origin/Referer headers are not checked

  if (httpMethod === 'PUT' && event.path === '/profile/update') {
    // Update user profile - vulnerable to CSRF
    const { email, displayName, role } = body;

    const updateParams = {
      TableName: 'UserProfiles',
      Key: { userId: authenticatedUserId },
      UpdateExpression: 'SET email = :email, displayName = :name, #r = :role, updatedAt = :ts',
      ExpressionAttributeNames: { '#r': 'role' },
      ExpressionAttributeValues: {
        ':email': email || '',
        ':name': displayName || '',
        ':role': role || 'user',
        ':ts': Date.now()
      }
    };

    await dynamodb.update(updateParams).promise();

    return {
      statusCode: 200,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ message: 'Profile updated', userId: authenticatedUserId })
    };
  }

  if (httpMethod === 'POST' && event.path === '/profile/transfer-ownership') {
    // Transfer resource ownership - high-impact action vulnerable to CSRF
    const { resourceId, newOwnerId } = body;

    const transferParams = {
      TableName: 'Resources',
      Key: { resourceId: resourceId },
      UpdateExpression: 'SET ownerId = :newOwner, previousOwner = :prevOwner, transferredAt = :ts',
      ConditionExpression: 'ownerId = :currentOwner',
      ExpressionAttributeValues: {
        ':newOwner': newOwnerId,
        ':prevOwner': authenticatedUserId,
        ':currentOwner': authenticatedUserId,
        ':ts': Date.now()
      }
    };

    try {
      await dynamodb.update(transferParams).promise();
      return {
        statusCode: 200,
        body: JSON.stringify({ message: 'Ownership transferred', resourceId, newOwnerId })
      };
    } catch (err) {
      if (err.code === 'ConditionalCheckFailedException') {
        return { statusCode: 403, body: JSON.stringify({ error: 'Not resource owner' }) };
      }
      throw err;
    }
  }

  return { statusCode: 404, body: JSON.stringify({ error: 'Not found' }) };
};

function parseCookies(cookieString) {
  const cookies = {};
  if (!cookieString) return cookies;
  cookieString.split(';').forEach(cookie => {
    const [name, ...rest] = cookie.trim().split('=');
    cookies[name] = rest.join('=');
  });
  return cookies;
}
